/*
* This script compiles modules for evaluating polynomial functions. If any polynomial coefficients change, this script should be rerun to update the compiled files.
*/
'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var writeFileSync = require( '@stdlib/fs/write-file' ).sync;
var currentYear = require( '@stdlib/time/current-year' );
var substringBefore = require( '@stdlib/string/substring-before' );
var substringAfter = require( '@stdlib/string/substring-after' );
var format = require( '@stdlib/string/format' );
var licenseHeader = require( '@stdlib/_tools/licenses/header' );
var compile = require( '@stdlib/math/base/tools/evalrational-compile' );
var compileC = require( '@stdlib/math/base/tools/evalrational-compile-c' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

// Polynomial coefficients ordered in ascending degree...

// Coefficients for erfinv on [0, 0.5]:
var P1 = [
	f32( -5.087819e-4 ),
	f32( -8.368748e-3 ),
	f32( 3.348066e-2 ),
	f32( -1.269262e-2 ),
	f32( -3.656380e-2 ),
	f32( 2.198787e-2 ),
	f32( 8.226879e-3 ),
	f32( -5.387730e-3 ),
	f32( 0.0 ),
	f32( 0.0 )
];
var Q1 = [
	f32( 1.0 ),
	f32( -9.700050e-1 ),
	f32( -1.565746e0 ),
	f32( 1.562216e0 ),
	f32( 6.623288e-1 ),
	f32( -7.122890e-1 ),
	f32( -5.273964e-2 ),
	f32( 7.952837e-2 ),
	f32( -2.333938e-3 ),
	f32( 8.862164e-4 )
];

// Coefficients for erfinv for 0.5 > 1-x >= 0:
var P2 = [
	f32( -2.024335e-1 ),
	f32( 1.052647e-1 ),
	f32( 8.370503e0 ),
	f32( 1.764473e1 ),
	f32( -1.885106e1 ),
	f32( -4.463823e1 ),
	f32( 1.744539e1 ),
	f32( 2.112947e1 ),
	f32( -3.671923e0 )
];
var Q2 = [
	f32( 1.0 ),
	f32( 6.242641e0 ),
	f32( 3.971344e0 ),
	f32( -2.866082e1 ),
	f32( -2.014326e1 ),
	f32( 4.856092e1 ),
	f32( 1.082687e1 ),
	f32( -2.264369e1 ),
	f32( 1.721148e1 )
];

// Coefficients for erfinv for sqrt( -log(1-x) ):
var P3 = [
	f32( -1.311028e-1 ),
	f32( -1.637940e-1 ),
	f32( 1.170302e-1 ),
	f32( 3.870797e-1 ),
	f32( 3.377855e-1 ),
	f32( 1.428695e-1 ),
	f32( 2.901579e-2 ),
	f32( 2.145590e-3 ),
	f32( -6.794656e-7 ),
	f32( 2.852253e-8 ),
	f32( -6.811500e-10 )
];
var Q3 = [
	f32( 1.0 ),
	f32( 3.466254e0 ),
	f32( 5.381683e0 ),
	f32( 4.778466e0 ),
	f32( 2.593019e0 ),
	f32( 8.488543e-1 ),
	f32( 1.522643e-1 ),
	f32( 1.105924e-2 ),
	f32( 0.0 ),
	f32( 0.0 ),
	f32( 0.0 )
];

var P4 = [
	f32( -3.503538e-2 ),
	f32( -2.224265e-3 ),
	f32( 1.855733e-2 ),
	f32( 9.508047e-3 ),
	f32( 1.871235e-3 ),
	f32( 1.575446e-4 ),
	f32( 4.604699e-6 ),
	f32( -2.304048e-10 ),
	f32( 2.663392e-12 )
];
var Q4 = [
	f32( 1.0 ),
	f32( 1.365335e0 ),
	f32( 7.620592e-1 ),
	f32( 2.200911e-1 ),
	f32( 3.415891e-2 ),
	f32( 2.638617e-3 ),
	f32( 7.646753e-5 ),
	f32( 0.0 ),
	f32( 0.0 )
];

var P5 = [
	f32( -1.674310e-2 ),
	f32( -1.129514e-3 ),
	f32( 1.056289e-3 ),
	f32( 2.093863e-4 ),
	f32( 1.496248e-5 ),
	f32( 4.496968e-7 ),
	f32( 4.625962e-9 ),
	f32( -2.811288e-14 ),
	f32( 9.905571e-17 )
];
var Q5 = [
	f32( 1.0 ),
	f32( 5.914293e-1 ),
	f32( 1.381519e-1 ),
	f32( 1.607461e-2 ),
	f32( 9.640118e-4 ),
	f32( 2.753355e-5 ),
	f32( 2.822432e-7 ),
	f32( 0.0 ),
	f32( 0.0 )
];

// Header to add to output files:
var header = licenseHeader( 'Apache-2.0', 'js', {
	'year': currentYear(),
	'copyright': 'The Stdlib Authors'
});
header += '\n/* This is a generated file. Do not edit directly. */\n';


// FUNCTIONS //

/**
* Inserts a compiled function into file content.
*
* @private
* @param {string} text - source content
* @param {string} id - function identifier
* @param {string} str - function string
* @returns {string} updated content
*/
function insert( text, id, str ) {
	var before;
	var after;
	var begin;
	var end;

	begin = '// BEGIN: '+id;
	end = '// END: '+id;

	before = substringBefore( text, begin );
	after = substringAfter( text, end );

	return format( '%s// BEGIN: %s\n\n%s\n%s%s', before, id, str, end, after );
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var fpath;
	var copts;
	var opts;
	var file;
	var str;

	opts = {
		'encoding': 'utf8'
	};

	fpath = resolve( __dirname, '..', 'lib', 'rational_p1q1.js' );
	str = header + compile( P1, Q1, { 'dtype': 'float32' } );
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p2q2.js' );
	str = header + compile( P2, Q2, { 'dtype': 'float32' } );
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p3q3.js' );
	str = header + compile( P3, Q3, { 'dtype': 'float32' } );
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p4q4.js' );
	str = header + compile( P4, Q4, { 'dtype': 'float32' } );
	writeFileSync( fpath, str, opts );

	fpath = resolve( __dirname, '..', 'lib', 'rational_p5q5.js' );
	str = header + compile( P5, Q5, { 'dtype': 'float32' } );
	writeFileSync( fpath, str, opts );

	copts = {
		'dtype': 'float',
		'name': ''
	};

	fpath = resolve( __dirname, '..', 'src', 'main.c' );
	file = readFileSync( fpath, opts );

	copts.name = 'rational_p1q1';
	str = compileC( P1, Q1, copts );
	file = insert( file, copts.name, str );

	copts.name = 'rational_p2q2';
	str = compileC( P2, Q2, copts );
	file = insert( file, copts.name, str );

	copts.name = 'rational_p3q3';
	str = compileC( P3, Q3, copts );
	file = insert( file, copts.name, str );

	copts.name = 'rational_p4q4';
	str = compileC( P4, Q4, copts );
	file = insert( file, copts.name, str );

	copts.name = 'rational_p5q5';
	str = compileC( P5, Q5, copts );
	file = insert( file, copts.name, str );

	writeFileSync( fpath, file, opts );
}

main();
